        <div class="edit-comment-hide">
  <task-lists disabled sortable>
    <div class="comment-body markdown-body js-comment-body soft-wrap user-select-contain d-block">
      <p dir="auto"><a class="user-mention notranslate" data-hovercard-type="user" data-hovercard-url="/users/amsv01/hovercard" data-octo-click="hovercard-link-click" data-octo-dimensions="link_type:self" href="https://github.com/amsv01">@amsv01</a></p>
<blockquote>
<p dir="auto">Looks to be what I was looking for but when tried to use arrows got following error message:</p>
<div class="highlight highlight-source-shell" dir="auto"><pre class="notranslate">line 200: read: -N: invalid option</pre></div>
<p dir="auto">Any idea how to fix this?</p>
<p dir="auto">P.S. I ran it on macOS just in case.</p>
</blockquote>
<p dir="auto">MacOS is still using bash v3 since some license foo. Bash v5 is current but the script should work with any bash v4.</p>
<p dir="auto">Use homebrew or ports to install a recent bash and just use it in your terminal only (don't replace your system's shell or make it available in system-wide PATH variable - only your user profile - since some there is still the danger that something in your system misbehaves PLUS you should NEVER touch Mac OSX system files. they are maintained by Apple ONLY).</p>
<p dir="auto">FYI <a href="https://www.quora.com/Why-does-MacOS-come-with-Bash-version-3-instead-of-Bash-version-4" rel="nofollow">https://www.quora.com/Why-does-MacOS-come-with-Bash-version-3-instead-of-Bash-version-4</a></p>
    </div>
  </task-lists>
  
</div>


