      <p dir="auto">Thanks for your idea.<br>
Look what i did: <a href="https://github.com/pedro-hs/checkbox.sh">https://github.com/pedro-hs/checkbox.sh</a></p>
<p dir="auto">Features:</p>
<ul dir="auto">
<li>Select only a option or multiple options</li>
<li>Select or unselect multiple options easily</li>
<li>Select all or unselect all</li>
<li>Pagination</li>
<li>Optional Vim keybinds</li>
<li>A .sh file with approximately 500 lines</li>
<li>Start with options selected</li>
<li>Show selected options counter for multiple options</li>
<li>Show custom message</li>
<li>Show current option index and options amount</li>
<li>Copy current option value to clipboard</li>
<li>Help tab when press h or wrongly call the script</li>
</ul>
    </div>
  </task-lists>
  
</div>


